// SCOUT - Normalise QCM + Form Inputs
// D1: two sources, one shape. Deliberately does NOT judge or filter (D4) -
// a filter with no human oversight is exactly where good ideas silently die.
// This node's only job is: messy input -> structured candidate + evidence link.

const RAW = {
  qcm: [
    { role: 'compliance-analyst', person: 'p1', reportedAt: '2026-08-11',
      problem: 'Manual SOC2 evidence collation',
      description: 'Screenshots copied by hand into the evidence folder weekly.',
      hoursPerWeek: 3, affected: 4, stress: 4 },
    { role: 'compliance-analyst', person: 'p2', reportedAt: '2026-08-11',
      problem: 'Chasing missing audit artefacts by hand',
      description: 'Same underlying pain as evidence collation, different words.',
      hoursPerWeek: 4, affected: 5, stress: 4 }
  ],
  form: [
    { role: 'security-analyst', person: 'p7', reportedAt: '2026-08-10',
      problem: 'Evidence folder always missing something at audit time',
      description: 'I end up rebuilding the evidence trail from scratch every quarter.',
      hoursPerWeek: 5, affected: 5, stress: 3 }
  ]
};

const out = [];
for (const [source, rows] of Object.entries(RAW)) {
  for (const r of rows) {
    out.push({ json: { candidate: {
      id: `${source}-${r.person}-${r.reportedAt}`,
      title: r.problem,
      role: r.role,
      source,
      person: r.person,
      reportedAt: r.reportedAt,
      hoursPerWeek: r.hoursPerWeek,
      affected: r.affected,
      stress: r.stress,
      description: r.description,
      evidenceLink: `${source}#${r.person}#${r.reportedAt}`,   // traceable back to raw source
      stage: 'normalised',
      log: [{ agent: 'Scout-Normalise', action: 'normalised', at: new Date().toISOString() }]
    }}});
  }
}
return out;

// SCOUT - Cluster Similar Candidates
// D9 test case 7: two teams raised the SAME problem in different words
// (evidence collation vs chasing missing artefacts). Scored separately,
// neither cleared 25% and both died - a real gap found while stress-testing
// this design. Fix: group semantically similar candidates and COMBINE their
// pools before scoring, so paraphrasing across teams can't kill a real signal.
//
// SKETCH: real clustering is an LLM/embedding job (OPEN — not implemented
// here). Stubbed as fuzzy title matching so the sketch stays readable.

function similar(a, b) {
  const wa = new Set(a.toLowerCase().split(/\W+/).filter(Boolean));
  const wb = new Set(b.toLowerCase().split(/\W+/).filter(Boolean));
  const overlap = [...wa].filter(w => wb.has(w)).length;
  return overlap >= 2; // crude stand-in for a real similarity model
}

const candidates = $input.all().map(i => i.json.candidate);
const clusters = [];

for (const c of candidates) {
  const match = clusters.find(cl => similar(cl.title, c.title));
  if (match) {
    match.members.push(c);
    match.rolesInvolved.add(c.role);
  } else {
    clusters.push({ title: c.title, members: [c], rolesInvolved: new Set([c.role]) });
  }
}

return clusters.map((cl, idx) => ({ json: { candidate: {
  id: 'cluster-' + idx,
  title: cl.members[0].title,
  clusteredFrom: cl.members.map(m => m.title),
  rolesInvolved: [...cl.rolesInvolved],
  reports: cl.members,
  stage: 'clustered',
  log: [{ agent: 'Scout-Cluster', action: 'clustered', memberCount: cl.members.length,
          note: cl.members.length > 1 ? 'pools combined across paraphrasing' : 'no match, single report' }]
}}}));

// SCORER - Threshold Check (25% role-pool, time-decayed)
// D2/D3: 25% of the ROLE POOL, not raw headcount, weight halving every
// quarter. 'A threshold may deprioritise an idea. It may never silently
// kill one' - so below-threshold does not mean discarded, it means routed
// differently (see the Switch node downstream).

const THRESHOLD = 0.25;
const HALF_LIFE_DAYS = 90;
const CONVICTION_HOURS = 4;
const CONVICTION_DESC_CHARS = 100;
const ROLE_POOL = { 'compliance-analyst': 4, 'security-analyst': 5, 'people-ops': 6 };

const now = Date.now();
const out = [];

for (const item of $input.all()) {
  const c = item.json.candidate;
  const roles = c.rolesInvolved || [c.role];
  // combined pool across every role represented in the cluster
  const pool = roles.reduce((sum, r) => sum + (ROLE_POOL[r] ?? 0), 0);
  const reports = c.reports || [c];

  if (!pool) {
    c.confidence = 0.2;
    c.unresolvedAssumptions = ['role-pool size unknown for: ' + roles.join(', ')];
    c.routing = { route: 'needs_context' };
    c.log.push({ agent: 'Scorer-Threshold', action: 'blocked', reason: 'unknown role-pool' });
    out.push({ json: { candidate: c } });
    continue;
  }

  const weighted = reports.reduce((sum, r) => {
    const ageDays = (now - new Date(r.reportedAt).getTime()) / 86400000;
    return sum + Math.pow(0.5, ageDays / HALF_LIFE_DAYS);
  }, 0);
  const decayedFraction = weighted / pool;

  const highConviction = reports.some(r =>
    r.source === 'form' &&
    (r.hoursPerWeek ?? 0) >= CONVICTION_HOURS &&
    (r.description || '').length >= CONVICTION_DESC_CHARS
  );

  c.threshold = { decayedFraction: Number(decayedFraction.toFixed(3)), thresholdUsed: THRESHOLD, pool };
  c.routing = decayedFraction >= THRESHOLD
    ? { route: 'high_signal' }
    : highConviction
      ? { route: 'low_signal_high_conviction' }
      : { route: 'below_threshold_no_evidence' };

  c.confidence = 0.85;
  c.unresolvedAssumptions = [];
  c.stage = 'thresholded';
  c.log.push({ agent: 'Scorer-Threshold', action: 'thresholded', route: c.routing.route, fraction: c.threshold.decayedFraction });
  out.push({ json: { candidate: c } });
}
return out;

// SCORER - fold LLM impact/sentiment scores back into candidate state
// State point worth keeping visible: the OpenAI node REPLACES the payload,
// so the candidate is explicitly re-attached here or it's lost. This is the
// concrete answer to 'how does state carry across agents' - re-attached at
// every LLM boundary, never assumed to survive.

const out = [];
const prior = $('SCORER — Threshold Check (25%, time-decayed)').all();

for (let i = 0; i < $input.all().length; i++) {
  const scored = $input.all()[i].json;
  const c = prior[i].json.candidate;

  const required = ['impactScore', 'sentimentScore', 'confidence', 'unresolvedAssumptions'];
  const missing = required.filter(k => !(k in scored));

  if (missing.length) {
    c.qc = { status: 'schema_failed', missing };
    c.routing = { route: 'needs_context' };
  } else {
    c.scores = scored;
    c.scores.sentimentCaveat = 'self-reported, gameable; weak signal cross-checked against hours lost + recurrence';
    c.confidence = scored.confidence;
    c.unresolvedAssumptions = scored.unresolvedAssumptions;
    if (scored.confidence < 0.5) c.routing = { route: 'needs_context' };
  }

  c.stage = 'scored';
  c.log.push({ agent: 'Scorer-Score', action: 'scores_merged', qc: c.qc?.status ?? 'ok', confidence: c.confidence });
  out.push({ json: { candidate: c } });
}
return out;

// SCORER - Rank + Cap Shortlist (top 3-5/week)
// D6/D10 fail-safe #3: a weekly batch paces input, but an uncapped shortlist
// against a reviewer's limited time grows a queue forever. Cap the list;
// everything below the cap PERSISTS with its scores and re-enters next
// week's ranking rather than being dropped.

const CAP = 5;

const all = $input.all().map(i => i.json.candidate);

// Blocked/low-confidence candidates are NOT filtered out here - they pass
// through to the Switch and route to ESCALATE. Dropping them at this point
// would be exactly the silent death the design promises never to allow.
const rankable = all.filter(c => c.routing?.route !== 'needs_context');
const blocked  = all.filter(c => c.routing?.route === 'needs_context');

rankable.sort((a, b) => (b.scores?.impactScore ?? 0) - (a.scores?.impactScore ?? 0));

rankable.forEach((c, idx) => {
  c.shortlistRank = idx + 1;
  c.shortlisted = idx < CAP;
  // The cap has to change the ROUTE, not just set a flag, or capped items
  // would still reach Gate 1 and the cap would be decorative.
  if (!c.shortlisted) c.routing = { route: 'capped_persist' };
  c.log.push({ agent: 'Scorer-Rank', action: c.shortlisted ? 'shortlisted' : 'capped_persist', rank: idx + 1 });
});

return [...rankable, ...blocked].map(c => ({ json: { candidate: c } }));

// GATE 1 - record the AI lead's decision (append-only)
const c = $json.candidate ?? $('GATE 1 — Wait: Worth our time? (AI Lead)').first().json.candidate;
const decision = $json.body ?? { approved: true, reviewer: 'ai-impl-lead', decisionMs: 4200 };

c.gate1 = {
  reviewer: 'AI implementation team lead',
  question: 'Is this worth our time?',
  approved: decision.approved !== false,
  decisionMs: decision.decisionMs ?? null,
  decidedAt: new Date().toISOString()
};
c.stage = c.gate1.approved ? 'gate1_approved' : 'gate1_rejected';
c.log.push({ agent: 'Gate1-Human', action: c.stage, decisionMs: c.gate1.decisionMs });
return [{ json: { candidate: c } }];

// RUBBER-STAMP DETECTOR
// D10 fail-safe #1: gate rejection rate is a metric, but a metric with no
// mechanism is decorative. If a reviewer approves N consecutive items in
// under X seconds each, flag it - the review almost certainly wasn't real.

const N_CONSECUTIVE = 3;
const X_SECONDS = 10;

// SKETCH: reads recent gate decisions for this reviewer from the decision
// log store. Stubbed as the current item's timing only.
const c = $json.candidate;
const decisionMs = c.gate1?.decisionMs ?? c.gate2?.decisionMs ?? c.gate3?.decisionMs;
const suspiciouslyFast = decisionMs != null && decisionMs < X_SECONDS * 1000;

if (suspiciouslyFast) {
  c.rubberStampFlag = {
    flagged: true,
    reason: `decision made in ${decisionMs}ms, below ${X_SECONDS}s threshold`,
    note: `PLATFORM: track streak per-reviewer; flag at ${N_CONSECUTIVE} consecutive fast approvals`
  };
  c.log.push({ agent: 'RubberStampDetector', action: 'flagged', decisionMs });
} else {
  c.log.push({ agent: 'RubberStampDetector', action: 'ok' });
}

return [{ json: { candidate: c } }];

// VALIDATE - Schema + Semantic Check (D7)
// Shape validation alone is insufficient - syntactically valid JSON can still
// describe a different problem than the one raised. So this checks MEANING,
// not just structure: does the PRD's user list match the role-pool that
// actually reported it, do stated time savings fall in the same range as
// reported hours lost, does scope reference Scout's evidence.
// Retry once with the error fed back; escalate on second failure - never
// pass bad data downstream.

// The Definer is an LLM node, so its output IS the PRD - it replaces the
// payload entirely and the candidate does not survive it. State is therefore
// re-attached from the last node that emitted it, and the PRD is taken from
// this node's own input. Getting this wrong is silent: the workflow would
// read `undefined.prd` and die one node later with no clue why.
const c = $('GATE 1 — Record Decision').first().json.candidate;
const prd = $json;
c.prd = prd;

// Retry count must come from $runIndex, NOT from the candidate object.
// On a loop-back, $('GATE 1 — Record Decision') returns the same snapshot
// every time, so a counter stored on the candidate would reset to 0 forever
// and the retry loop would never terminate.
const retryCount = $runIndex;

const shapeOk = prd && prd.problem && Array.isArray(prd.users) && Array.isArray(prd.requirements) && Array.isArray(prd.successCriteria);

const reportedRoles = new Set((c.reports || [c]).map(r => r.role));
const usersMatchRoles = shapeOk && prd.users.some(u =>
  [...reportedRoles].some(r => u.toLowerCase().includes(r.split('-')[0])));

const reports = c.reports || [c];
const claimedHours = shapeOk ? (prd.claimedTimeSavingHrsPerWeek ?? null) : null;
const reportedHours = reports.reduce((s, r) => s + (r.hoursPerWeek ?? 0), 0) / reports.length;
// Guard the zero case explicitly - with reportedHours at 0 the tolerance
// window collapses to zero width and every non-zero claim fails.
const hoursInRange = claimedHours == null || reportedHours === 0
  || Math.abs(claimedHours - reportedHours) <= reportedHours * 0.6;

const semanticOk = usersMatchRoles && hoursInRange;

if (!shapeOk || !semanticOk) {
  const errors = [
    !shapeOk && 'missing required PRD fields',
    !usersMatchRoles && 'PRD user list does not match the role-pool that reported this problem',
    !hoursInRange && 'claimed time saving is far outside the reported hours lost'
  ].filter(Boolean);

  // Retry ONCE, then escalate - D7. Three outcomes, so the node downstream
  // is a Switch, not an IF: an IF has nowhere to put 'escalate' and would
  // silently loop failures back to the Definer forever.
  c.validationErrors = errors;   // fed back into the retry prompt
  c.routing2 = retryCount < 1 ? 'retry' : 'escalate';
  if (c.routing2 === 'escalate') {
    c.unresolvedAssumptions = [...(c.unresolvedAssumptions || []), ...errors];
  }
  c.log.push({ agent: 'Validate', action: c.routing2, attempt: retryCount + 1, errors });
} else {
  c.routing2 = 'ok';
  c.log.push({ agent: 'Validate', action: 'passed_shape_and_semantic_check', attempt: retryCount + 1 });
}

return [{ json: { candidate: c } }];

// SELF-CRITIQUE - fold the checklist result back into state
const critique = $json;
const c = $('VALIDATE — Schema + Semantic Check').first().json.candidate;

c.prdSelfCritique = critique;
c.stage = 'prd_self_critiqued';
c.log.push({ agent: 'SelfCritique', action: 'checked', passed: critique.passed });
return [{ json: { candidate: c } }];

// GATE 2 - apply the requester's edits to the PRD
const c = $('GATE 2 — Wait: Understood correctly? (Requester)').first().json.candidate;
const edits = $json.body?.prdEdits ?? {};
const decision = $json.body ?? { decisionMs: 30000 };

c.prd = { ...c.prd, ...edits };
c.gate2 = {
  reviewer: 'the person who raised the problem',
  question: 'Did the system understand the problem correctly?',
  editedFields: Object.keys(edits),
  decisionMs: decision.decisionMs ?? null,
  approvedAt: new Date().toISOString()
};
c.stage = 'prd_approved';
c.log.push({ agent: 'Gate2-Human', action: 'prd_approved', editedFields: c.gate2.editedFields });
return [{ json: { candidate: c } }];

// GATE 3 - record the AI lead's ship/no-ship decision
const c = $('GATE 3 — Wait: Safe to ship? (AI Lead)').first().json.candidate;
const decision = $json.body ?? { approved: true, decisionMs: 8000 };

c.gate3 = {
  reviewer: 'AI implementation team lead',
  question: 'Is it safe to put this live?',
  approved: decision.approved !== false,
  decisionMs: decision.decisionMs ?? null,
  ambiguityFlag: c.builderAmbiguityFlag ?? null,  // D8: Builder's own flag surfaces here
  decidedAt: new Date().toISOString()
};
c.stage = c.gate3.approved ? 'gate3_approved' : 'gate3_halted';
c.log.push({ agent: 'Gate3-Human', action: c.stage });
return [{ json: { candidate: c } }];

// 30-DAY REVIEW - still in use?
// D10 fail-safe #2: the pipeline used to end at deploy, with nothing
// handling a tool that ships and turns out useless or wrong. The 30-day
// usage metric becomes a TRIGGER here, not just a number in a report.

const c = $json.candidate ?? { id: 'placeholder', title: 'placeholder' };

// SKETCH: real usage telemetry comes from the platform. Stubbed.
const usageEvents30d = c.usageEvents30d ?? 7;

c.review30Day = {
  usageEvents30d,
  stillInUse: usageEvents30d > 0,
  checkedAt: new Date().toISOString()
};
c.log = [...(c.log || []), { agent: 'Review30Day', action: c.review30Day.stillInUse ? 'confirmed_in_use' : 'flagged_unused' }];
return [{ json: { candidate: c } }];
